import { CommonModule } from '@angular/common';
import { Component, Input, OnInit } from '@angular/core';
import { FieldInputComponent } from '../field-input/field-input.component';
import { FormsFieldModel } from 'src/app/shared/models/forms-field.model';
import { FieldArrayComponent } from '../field-array/field-array.component';

@Component({
  selector: 'mf-forms-field-object',
  imports: [CommonModule, FieldInputComponent, FieldArrayComponent],
  templateUrl: './field-object.component.html',
  styleUrls: ['./field-object.component.scss'],
  standalone: true,
})
export class FieldObjectComponent implements OnInit{
  private colors: string[] = [
      '#ffadad',
      '#ffd6a5',
      '#fdffb6',
      '#caffbf',
      '#9bf6ff',
      '#a0c4ff',
      '#bdb2ff',
      '#ffc6ff',
    ]
  currentColor: string = 'white';
  @Input() formsField!: FormsFieldModel;
  @Input() color!: number;
  outputColor: number = 0;
  constructor() {
  }
  ngOnInit(): void {
    this.currentColor = this.colors.at(this.color % 7)!;
    this.outputColor = this.color + 1;
  }
}
